/** Розгорнутий внутрішній JSON дзеркала на 3 характерні області. */
export function mirrorLiveInnerPayload(): Record<string, unknown> {
  return {
    date_today: MIRROR_LIVE_DATE_TODAY,
    date_tomorrow: MIRROR_LIVE_DATE_TOMORROW,
    regions: [
      chernihivRegionFactory(),
      lvivRegionFactory(),
      poltavaCompactRegionFactory(),
    ],
  };
}

/** Сира відповідь проксі-дзеркала: рядок у body та позначка часу. */
export function mirrorLiveRaw(): { body: string; timestamp: string } {
  return {
    body: JSON.stringify(mirrorLiveInnerPayload()),
    timestamp: MIRROR_LIVE_TIMESTAMP,
  };
}
